/**
 * The freeze an archived project puts on its issues.
 *
 * While a project is archived, its issues and everything attached to them
 * (comments, attachments, assignment, status) are read-only. The rule is
 * derived from the project row on every write rather than stored on the
 * issues, so restoring the project lifts it without touching a single issue.
 *
 * Must call (do not reimplement): assertNotArchived
 */
import { assertNotArchived } from "@/lib/soft-delete";
import * as projectRepo from "@/server/repositories/project-repository";
import { requireFound } from "./_support";
import type { OrgId, ProjectId } from "@/types/common";

/**
 * Throws `AlreadyArchivedError` for the project when it is archived. Call it
 * after the permission and issue/comment checks so those keep precedence, and
 * before anything is written or published.
 */
export async function assertProjectNotFrozen(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertNotArchived("Project", project.id, project);
}

