/**
 * An archived project freezes its issues: every write on them (and on their
 * comments and attachments) is refused, reads keep working, and restoring the
 * project lifts the freeze again.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";

const NOW = new Date("2026-06-01T07:00:00.000Z");
const PAST = "2026-01-01T00:00:00.000Z";

let cleanup: () => void;
let tenant: Tenant;
let issue: Issue;
let comment: Comment;
let attachmentId: string;
const published: string[] = [];
const detachers: Unsubscribe[] = [];

const EVENTS = [
  "issue.created",
  "issue.updated",
  "issue.status_changed",
  "issue.assigned",
  "issue.archived",
  "issue.overdue",
  "comment.created",
  "comment.deleted",
] as const;

async function archiveProject(archiveIssues = false) {
  await projectService.archiveProject(tenant.actors.owner, {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    archiveIssues,
  });
}

async function restoreProject() {
  await projectService.restoreProject(tenant.actors.owner, tenant.org.id, tenant.project.id);
}

async function expectFrozen(write: () => Promise<unknown>) {
  published.length = 0;
  await expect(write()).rejects.toBeInstanceOf(AlreadyArchivedError);
  expect(published).toEqual([]);
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("freeze");
  await usageRepo.recomputeUsage(tenant.org.id);
  resetOverdueTracking();

  issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Frozen soon", dueAt: PAST }),
  );
  comment = await commentService.createComment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    body: "Before the freeze",
    parentId: null,
    mentionedUserIds: [],
  });
  const attachment = await attachmentService.addAttachment(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    filename: "spec.pdf",
    contentType: "application/pdf",
    sizeBytes: 1024,
  });
  attachmentId = attachment.id;

  for (const type of EVENTS) {
    detachers.push(
      subscribe(type, () => {
        published.push(type);
      }),
    );
  }
});

afterEach(() => {
  published.length = 0;
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

describe("archived project freezes its issues", () => {
  it("refuses every write while the project is archived and keeps reads working", async () => {
    await archiveProject();

    await expectFrozen(() =>
      issueService.updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Renamed",
      }),
    );
    await expectFrozen(() =>
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "in_progress",
      }),
    );
    await expectFrozen(() =>
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: issue.status,
      }),
    );
    await expectFrozen(() =>
      issueService.moveIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toStatus: "done",
        toIndex: 0,
      }),
    );
    await expectFrozen(() =>
      issueService.assignIssue(tenant.actors.admin, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.member,
      }),
    );
    await expectFrozen(() =>
      issueService.assignIssue(tenant.actors.admin, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: null,
      }),
    );
    await expectFrozen(() =>
      issueService.archiveIssue(tenant.actors.admin, tenant.org.id, issue.id),
    );
    await expectFrozen(() =>
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "Late thought",
        parentId: null,
        mentionedUserIds: [],
      }),
    );
    await expectFrozen(() =>
      commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "Edited",
      }),
    );
    await expectFrozen(() =>
      commentService.deleteComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    );
    await expectFrozen(() =>
      attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        filename: "late.png",
        contentType: "image/png",
        sizeBytes: 2048,
      }),
    );
    await expectFrozen(() =>
      attachmentService.removeAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        attachmentId: attachmentId as never,
      }),
    );

    // Nothing changed, and every read still works.
    const read = await issueService.getIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(read.issue.title).toBe("Frozen soon");
    expect(read.issue.status).toBe(issue.status);
    expect(read.issue.assigneeId).toBeNull();
    expect(read.issue.archivedAt).toBeNull();
    expect(read.commentCount).toBe(1);
    expect(read.attachmentCount).toBe(1);

    const thread = await commentService.getThread(tenant.actors.member, tenant.org.id, issue.id);
    expect(thread).toHaveLength(1);
    const attachments = await attachmentService.listAttachments(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );
    expect(attachments).toHaveLength(1);
    const board = await issueService.getBoard(tenant.actors.member, tenant.org.id, tenant.project.id);
    expect(board.flatMap((column) => column.issues).map((row) => row.id)).toContain(issue.id);

    await restoreProject();
  });

  it("keeps permission errors ahead of the freeze", async () => {
    await archiveProject();

    await expect(
      issueService.updateIssue(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Nope",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      commentService.createComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "Nope",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await restoreProject();
  });

  it("lifts the freeze when the project is restored", async () => {
    await archiveProject();
    await restoreProject();

    const updated = await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "Thawed",
    });
    expect(updated.title).toBe("Thawed");

    const posted = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "Back in business",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: posted.id,
    });
    await attachmentService.removeAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      attachmentId: attachmentId as never,
    });
  });

  it("never announces an issue of an archived project as overdue, until it is restored", async () => {
    const overdue: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      overdue.push(payload.issueId);
    });

    try {
      await archiveProject();
      await runOverdueIssueJob(NOW);
      expect(overdue).toEqual([]);

      await restoreProject();
      await runOverdueIssueJob(new Date(NOW.getTime() + 60_000));
      expect(overdue).toContain(issue.id);
    } finally {
      off();
    }
  });

  it("reports an archived issue as itself rather than as its project", async () => {
    const other = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived first" }),
    );
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, other.id);
    await archiveProject();

    const error = await issueService
      .updateIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: other.id,
        title: "Renamed",
      })
      .catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(AlreadyArchivedError);
    expect((error as AlreadyArchivedError).entity).toBe("Issue");

    await restoreProject();
    await expect(issueRepo.findIssueById(tenant.org.id, other.id)).resolves.not.toBeNull();
  });
});

